import "./badge.css";

import type { ComponentProps } from "react";
import { cx } from "./cx";

export type BadgeTone = "default" | "accent" | "success" | "warning" | "danger";

export type BadgeProps = ComponentProps<"span"> & {
  tone?: BadgeTone | undefined;
};

export function Badge({ tone = "default", className, ...rest }: BadgeProps) {
  return (
    <span className={cx("ns-badge", className)} data-tone={tone} {...rest} />
  );
}

@layer components {
  .ns-badge {
    display: inline-flex;
    align-items: center;
    padding: var(--space-1, 0.25rem) var(--space-4, 0.49rem);
    border: 1px solid var(--face-line, #626262);
    border-radius: var(--radius, 0.4rem);
    font: inherit;
    font-size: var(--type-sm, 0.8rem);
    line-height: var(--leading-tight, 1.25);
    color: var(--on-key, #111);
    background: var(--face);
    background-clip: padding-box;
    box-shadow: var(--float, 0 8px 20px rgb(0 0 0 / 12%));
  }

  .ns-badge[data-tone="accent"] {
    color: var(--on-key, #111);
    border-color: var(--key-line, #221898);
    background: var(--key-face);
    box-shadow: var(--float, 0 8px 20px rgb(0 0 0 / 12%));
  }

  .ns-badge[data-tone="success"] {
    color: var(--success, #2f6b3a);
  }

  .ns-badge[data-tone="warning"] {
    color: var(--warning, #8a5a12);
  }

  .ns-badge[data-tone="danger"] {
    color: var(--error, #8f3232);
  }
}
